export function createAxiosClient({ baseURL = '', headers = {}, token } = {}) {
  const call = async (path, method, data) => {
    const accessToken = token || localStorage.getItem('base44_access_token');
    const response = await fetch(baseURL + path, { method, credentials: 'same-origin', headers: { ...headers, ...(accessToken ? { Authorization: 'Bearer ' + accessToken } : {}), ...(data !== undefined ? { 'Content-Type': 'application/json' } : {}) }, body: data === undefined ? undefined : JSON.stringify(data) });
    const body = await response.json().catch(() => ({}));
    if (!response.ok) { const error = new Error(body.error || 'Request failed'); error.status = response.status; error.data = body; error.response = { status: response.status, data: body }; throw error; }
    return body;
  };
  return { get: path => call(path, 'GET'), post: (path, data) => call(path, 'POST', data), patch: (path, data) => call(path, 'PATCH', data), delete: path => call(path, 'DELETE'), defaults: { headers, baseURL } };
}

const tokenKey = 'base44_access_token';
const sessionToken = () => localStorage.getItem(tokenKey) || '';
function fail(response, data) {
  const error = new Error(data?.error || data?.message || 'Request failed (' + response.status + ')');
  error.status = response.status; error.data = data; error.response = { status: response.status, data }; return error;
}
export function createClient(config = {}) {
  if (config.token) localStorage.setItem(tokenKey, config.token);
  const request = async (path, method = 'GET', data, native = false) => {
    const form = typeof FormData !== 'undefined' && data instanceof FormData;
    const token = sessionToken();
    const headers = { ...(token ? { Authorization: 'Bearer ' + token } : {}), ...(!form && data !== undefined ? { 'Content-Type': 'application/json' } : {}) };
    const response = await fetch(path, { method, headers, credentials: 'same-origin', body: data === undefined ? undefined : form ? data : JSON.stringify(data) });
    if (native) return response;
    const body = await response.json().catch(() => ({})); if (!response.ok) throw fail(response, body); return body;
  };
  const invoke = async (name, data = {}) => {
    let body = data;
    if (Object.values(data).some(value => value instanceof File || value instanceof Blob)) {
      body = new FormData(); for (const [key, value] of Object.entries(data)) body.append(key, value instanceof Blob ? value : typeof value === 'object' ? JSON.stringify(value) : String(value));
    }
    return { data: await request('/api/functions/' + encodeURIComponent(name), 'POST', body) };
  };
  const client = {
    setToken: token => token ? localStorage.setItem(tokenKey, token) : localStorage.removeItem(tokenKey),
    cleanup: () => {},
    auth: {
      me: () => request('/api/auth/me'),
      get_logged_user: () => request('/api/auth/me'),
      isAuthenticated: async () => { try { await request('/api/auth/me'); return true; } catch { return false; } },
      updateMe: data => request('/api/auth/me', 'PATCH', data),
      loginViaEmailPassword: async (email, password) => { const data = await request('/api/auth/login', 'POST', { email, password }); client.setToken(data.access_token); return data; },
      register: data => request('/api/auth/register', 'POST', data),
      logout: async redirect => { try { await request('/api/auth/logout', 'POST', {}); } finally { client.setToken(''); if (typeof redirect === 'string') { const target=new URL(redirect,location.origin);location.href=target.origin===location.origin?target.pathname+target.search:'/standalone-login'; } else if(redirect===true)location.href='/standalone-login'; } },
      redirectToLogin: returnTo => { const next = new URL(returnTo || location.href, location.origin); location.href = '/standalone-login?next=' + encodeURIComponent(next.origin === location.origin ? next.pathname + next.search : '/'); },
      loginWithProvider: async () => { throw new Error('Configure a standalone OAuth provider before using social sign-in. Email/password login is available.'); },
    },
    entities: new Proxy({}, { get: (_, name) => {
      if (typeof name !== 'string' || name === 'then') return undefined;
      const call = (operation, args = []) => request('/api/entities/' + encodeURIComponent(name) + '/' + operation, 'POST', { args });
      return {
        ...Object.fromEntries(['list','filter','get','create','update','delete','count','bulkCreate','bulkUpdate','deleteMany','updateMany','aggregate'].map(operation => [operation, (...args) => call(operation, args)])),
        subscribe: callback => {
          const stream = new EventSource('/api/events?entity=' + encodeURIComponent(name));
          stream.onmessage = event => { try { callback(JSON.parse(event.data)); } catch {} };
          return () => stream.close();
        },
      };
    } }),
    functions: { invoke, fetch: (path, options = {}) => fetch('/api/functions/' + path.replace(/^\//, ''), { ...options, credentials: 'same-origin', headers: { ...options.headers, ...(sessionToken() ? { Authorization: 'Bearer ' + sessionToken() } : {}) } }) },
    integrations: { Core: new Proxy({}, { get: (_, action) => async data => {
      let body = data || {};
      if (Object.values(body).some(value => value instanceof File || value instanceof Blob)) {
        body = new FormData(); for (const [key, value] of Object.entries(data)) body.append(key, value instanceof Blob ? value : typeof value === 'object' ? JSON.stringify(value) : String(value));
      }
      return request('/api/integrations/' + encodeURIComponent(action), 'POST', body);
    } }) },
    users: { inviteUser: (email, role) => request('/api/users/invite', 'POST', { email, role }) },
    appLogs: { logUserInApp: page => request('/api/events/log', 'POST', { name: 'page_view', data: { page } }) },
    analytics: { track: (name, data) => request('/api/events/log', 'POST', { name, data }) },
    agents: {
      createConversation: data => request('/api/agents/conversations', 'POST', data),
      getConversation: id => request('/api/agents/conversations/' + encodeURIComponent(id)),
      listConversations: data => request('/api/agents/conversations/list', 'POST', data || {}),
      addMessage: (conversation, message) => request('/api/agents/conversations/' + encodeURIComponent(typeof conversation === 'object' ? conversation.id : conversation) + '/messages', 'POST', message),
      subscribeToConversation: (id, callback) => { let active = true; const poll = async () => { try { const data = await client.agents.getConversation(id); if (active) callback(data); } catch {} }; poll(); const timer = setInterval(poll, 2000); return () => { active = false; clearInterval(timer); }; },
    },
    actors: new Proxy({}, { get: (_, name) => id => ({ connect: () => {
      const socket = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '/api/actors/' + encodeURIComponent(name) + '/' + encodeURIComponent(id));
      const callbacks = new Set(), queue = [];
      socket.onopen = () => { for (const message of queue.splice(0)) socket.send(message); };
      socket.onmessage = event => { let data; try { data = JSON.parse(event.data); } catch { return; } for (const callback of callbacks) callback(data); };
      return { send: data => { const text = JSON.stringify(data); if (socket.readyState === WebSocket.OPEN) socket.send(text); else if (socket.readyState === WebSocket.CONNECTING) queue.push(text); },
        subscribe: callback => { callbacks.add(callback); return () => callbacks.delete(callback); }, close: () => socket.close() };
    } }) }),
  };
  Object.defineProperty(client, 'asServiceRole', { get: () => { throw new Error('Service-role access is unavailable in the browser.'); } });
  return client;
}

import { runtime } from './context.mjs';
import { makeClient } from './sdk.mjs';

export class Actor {
  constructor(options) {
    this.options = options;
    const app = runtime(), prefix = 'actor:' + options.name + ':' + options.id + ':';
    this.client = makeClient({ service: true, user: null });
    this.storage = {
      get: async key => { const row = app.store.db.prepare('SELECT value FROM settings WHERE key=?').get(prefix + key); return row ? JSON.parse(row.value) : undefined; },
      put: async (key, value) => { app.store.db.prepare('INSERT INTO settings(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(prefix + key, JSON.stringify(value)); },
      delete: async key => { app.store.db.prepare('DELETE FROM settings WHERE key=?').run(prefix + key); },
    };
    this.connections = new Map();
  }
  getConnections() { return [...this.connections.values()]; }
  broadcast(data) { for (const connection of this.connections.values()) connection.send(data); }
}

import { readdir, readFile, access } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { randomBytes } from 'node:crypto';
import { Store } from './store.mjs';
import { Auth } from './auth.mjs';
import { Files } from './files.mjs';
import { Integrations } from './integrations.mjs';
import { requestContext, setRuntime } from './context.mjs';
import { makeClient } from './sdk.mjs';
import { HttpError } from './query.mjs';

export class App {
  constructor(options = {}) {
    this.root = resolve(options.root || '.');
    this.publicUrl = (process.env.PUBLIC_URL || 'http://localhost:' + (process.env.PORT || 3000)).replace(/\/$/, '');
    this.store = new Store({ path: options.db || process.env.DATABASE_PATH || 'data/app.sqlite', schemaDir: resolve(this.root, 'base44/entities') });
    this.auth = new Auth(this.store);
    this.files = new Files(this.store, options.uploadDir || process.env.UPLOAD_DIR || resolve(this.root, 'data/uploads'), this.publicUrl);
    this.integrations = new Integrations(this);
    this.functionModules = new Map();
    this.agents = new Map();
    setRuntime(this);
    process.env.APP_URL ||= this.publicUrl;
    process.env.BASE44_APP_ID ||= 'standalone';
    globalThis.Deno = { env: { get: key => process.env[key], toObject: () => ({ ...process.env }) } };
  }
  async initialize() {
    const agentDirectory = resolve(this.root, 'base44/agents');
    for (const name of await readdir(agentDirectory).catch(() => [])) {
      if (!/\.jsonc?$/.test(name)) continue;
      const config = JSON.parse(await readFile(resolve(agentDirectory, name), 'utf8'));
      this.agents.set(config.name || name.replace(/\.jsonc?$/, ''), config);
    }
    if (process.env.ADMIN_EMAIL && process.env.ADMIN_PASSWORD && !this.store.db.prepare('SELECT email FROM identities LIMIT 1').get()) {
      await this.auth.create({ email: process.env.ADMIN_EMAIL, password: process.env.ADMIN_PASSWORD, full_name: process.env.ADMIN_NAME || 'Administrator', role: 'admin' });
    }
  }
  async loadFunction(name) {
    if (!/^[A-Za-z0-9_-]{1,100}$/.test(name)) throw new HttpError(404, 'Function not found.');
    if (!this.functionModules.has(name)) {
      const promise = (async () => {
        let path = resolve(this.root, 'base44/functions', name, 'entry.ts');
        if (!await access(path).then(() => true, () => false)) path = resolve(this.root, 'base44/functions', name, 'entry.js');
        return import(pathToFileURL(path).href);
      })().then(module => {
        if (typeof module.default !== 'function') throw new HttpError(501, 'Function ' + name + ' has no request handler.');
        return module.default;
      }).catch(error => { this.functionModules.delete(name); if (error.code === 'ERR_MODULE_NOT_FOUND') throw new HttpError(503, 'Function dependency missing for ' + name + '. See the migration report.'); throw error; });
      this.functionModules.set(name, promise);
    }
    return await this.functionModules.get(name);
  }
  async callFunction(name, request, context) {
    const handler = await this.loadFunction(name);
    const response = await requestContext.run(context, () => handler(request));
    if (!(response instanceof Response)) throw new HttpError(500, 'Function did not return a Response.');
    return response;
  }
  async invoke(name, data, context) {
    const headers = { 'Content-Type': 'application/json', ...(context.request ? Object.fromEntries(['authorization','cookie'].map(key => [key, context.request.headers.get(key)]).filter(([,value]) => value)) : {}) };
    const response = await this.callFunction(name, new Request(this.publicUrl + '/functions/' + name, { method: 'POST', headers, body: JSON.stringify(data || {}) }), context);
    const body = await response.json().catch(() => ({}));
    if (!response.ok) throw new HttpError(response.status, body.error || 'Function failed.');
    return body;
  }
  async integrate(action, data, context) { return this.integrations.call(action, data, context); }
  async log(name, data, context) {
    if (!context.user) throw new HttpError(401, 'Sign in required.');
    this.store.create('RuntimeEvent', { name, payload: data, user_id: context.user.id }, { ...context, service: true });
    return { success: true };
  }
  async invite(email, role = 'user', context) {
    if (context.user?.role !== 'admin') throw new HttpError(403, 'Administrator access required.');
    if (!['user','admin'].includes(role)) throw new HttpError(400, 'Invalid role.');
    if (!process.env.RESEND_API_KEY || !process.env.EMAIL_FROM) throw new HttpError(503, 'Configure email delivery before inviting users.');
    const token = randomBytes(32).toString('base64url');
    const invitation = this.store.create('RuntimeInvitation', { email: String(email).toLowerCase(), role, token, expires: Date.now() + 48 * 3600000, user_id: context.user.id }, { ...context, service: true });
    await this.integrations.email({ to: email, subject: 'Your application invitation', body: '<p>You have been invited. Open this link to create your account:</p><p><a href="' + this.publicUrl + '/standalone-login?invite=' + encodeURIComponent(token) + '">Create account</a></p>' });
    return { success: true, invitation_id: invitation.id };
  }
  conversation(id, context) {
    const record = this.store.get('RuntimeConversation', id, context);
    return { ...record, messages: record.messages || [] };
  }
  async agentMessage(id, message, context) {
    const conversation = this.conversation(id, context);
    const agent = this.agents.get(conversation.agent_name);
    if (!agent) throw new HttpError(404, 'Agent not found.');
    const text = String(message.content || '');
    if (!text.trim() || text.length > 30000) throw new HttpError(400, 'Message must contain 1–30,000 characters.');
    const messages = [...conversation.messages.slice(-100), { id: crypto.randomUUID(), role: 'user', content: text, created_date: new Date().toISOString() }];
    const tools = agent.tool_configs || [];
    const schemas = tools.filter(tool => tool.entity_name).map(tool => ({ name: tool.entity_name, operations: tool.allowed_operations, fields: this.store.schemas.get(tool.entity_name)?.properties || {} }));
    const client = makeClient(context), outcomes = [];
    let reply = '';
    for (let round = 0; round < 5; round++) {
      const result = await this.integrations.llm({
        prompt: agent.instructions + '\nAvailable entity tools: ' + JSON.stringify(schemas) + '\nAvailable functions: ' + JSON.stringify(tools.filter(tool => tool.function_name)) +
          '\nConversation:\n' + JSON.stringify(messages).slice(-90000) + '\nActual tool results:\n' + JSON.stringify(outcomes).slice(-40000) +
          '\nReturn reply and actions. Use actions only from the configured tools, only as needed for the user request. Do not claim a successful action until its actual result is shown. Each action is {type:"entity"|"function",name,operation,args:[...]}. For entity operations use filter(query,sort,limit),get(id),create(data),update(id,data),delete(id). If no action is needed return an empty actions array.',
        response_json_schema: { type: 'object', properties: { reply: { type: 'string' }, actions: { type: 'array', items: { type: 'object' } } }, required: ['reply','actions'] },
      }, context);
      if (typeof result.reply !== 'string' || !Array.isArray(result.actions)) throw new HttpError(502, 'Agent returned an invalid action plan.');
      reply = result.reply;
      if (!result.actions.length) break;
      for (const action of result.actions.slice(0, 10)) {
        try {
          let data;
          if (action.type === 'entity') {
            const operation = action.operation, permission = ['filter','list','get','count','aggregate'].includes(operation) ? 'read' : operation;
            if (!['filter','list','get','count','aggregate','create','update','delete'].includes(operation) || !tools.some(tool => tool.entity_name === action.name && tool.allowed_operations?.includes(permission))) throw new HttpError(403, 'Tool is not allowed.');
            data = await client.entities[action.name][operation](...(action.args || []));
          } else if (action.type === 'function') {
            if (!tools.some(tool => tool.function_name === action.name)) throw new HttpError(403, 'Function tool is not allowed.');
            data = (await client.functions.invoke(action.name, action.args?.[0] || {})).data;
          } else throw new HttpError(400, 'Unknown tool type.');
          outcomes.push({ action, success: true, result: JSON.stringify(data).slice(0, 12000) });
        } catch (error) { outcomes.push({ action, success: false, error: error.message }); }
      }
      if (round === 4) reply = 'The tool-call limit was reached. Check the recorded results before continuing.';
    }
    messages.push({ id: crypto.randomUUID(), role: 'assistant', content: reply, tool_results: outcomes, created_date: new Date().toISOString() });
    return this.store.update('RuntimeConversation', id, { messages }, context);
  }
}

import { randomBytes, createHash, scrypt, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';
import { HttpError } from './query.mjs';
const derive = promisify(scrypt);
const digest = token => createHash('sha256').update(token).digest('hex');
export class Auth {
  constructor(store) { this.store = store; }
  async create({ email, password, full_name, role = 'user' }) {
    email = String(email || '').trim().toLowerCase();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254) throw new HttpError(400, 'Enter a valid email address.');
    if (typeof password !== 'string' || password.length < 12 || password.length > 256) throw new HttpError(400, 'Use a password between 12 and 256 characters.');
    if (this.store.db.prepare('SELECT email FROM identities WHERE email=?').get(email)) throw new HttpError(409, 'An account already exists for this email.');
    const salt = randomBytes(16).toString('hex');
    const hash = (await derive(password, salt, 64, { N: 32768, r: 8, p: 1, maxmem: 64 * 1024 * 1024 })).toString('hex');
    return this.store.atomic(() => {
      const profiles = this.store.query('User', {}, undefined, 50000, 0, { service: true }).filter(profile => String(profile.email || '').toLowerCase() === email);
      if (profiles.length > 1) throw new HttpError(409, 'Resolve duplicate imported user profiles before creating this account.');
      const details = { email, full_name: String(full_name || profiles[0]?.full_name || email), role };
      const user = profiles[0] ? this.store.update('User', profiles[0].id, details, { service: true }) : this.store.create('User', details, { service: true });
      this.store.db.prepare('INSERT INTO identities(email,user_id,salt,hash) VALUES (?,?,?,?)').run(email, user.id, salt, hash);
      return user;
    });
  }
  async login(email, password) {
    email = String(email || '').trim().toLowerCase();
    const identity = this.store.db.prepare('SELECT * FROM identities WHERE email=?').get(email);
    const salt = identity?.salt || '00000000000000000000000000000000';
    const candidate = await derive(String(password || '').slice(0, 256), salt, 64, { N: 32768, r: 8, p: 1, maxmem: 64 * 1024 * 1024 });
    if (!identity || !timingSafeEqual(candidate, Buffer.from(identity.hash, 'hex'))) throw new HttpError(401, 'Email or password is incorrect.');
    const user = this.store.raw('User', identity.user_id);
    if (!user || user.is_active === false) throw new HttpError(401, 'This account is unavailable.');
    const token = randomBytes(32).toString('base64url');
    this.store.db.prepare('INSERT INTO sessions(hash,user_id,expires) VALUES (?,?,?)').run(digest(token), user.id, Date.now() + 8 * 60 * 60 * 1000);
    this.store.db.prepare('DELETE FROM sessions WHERE expires<?').run(Date.now());
    return { access_token: token, token, user };
  }
  token(request) {
    const bearer = request.headers.get('authorization')?.match(/^Bearer (.+)$/i)?.[1];
    if (bearer) return bearer;
    return request.headers.get('cookie')?.match(/(?:^|;\s*)standalone_session=([^;]+)/)?.[1] || '';
  }
  user(request) {
    const token = this.token(request);
    if (!token) return null;
    const session = this.store.db.prepare('SELECT user_id FROM sessions WHERE hash=? AND expires>?').get(digest(token), Date.now());
    const user = session ? this.store.raw('User', session.user_id) : null;
    return user && user.is_active !== false ? user : null;
  }
  logout(request) {
    const token = this.token(request);
    if (token) this.store.db.prepare('DELETE FROM sessions WHERE hash=?').run(digest(token));
  }
}

import { AsyncLocalStorage } from 'node:async_hooks';
export const requestContext = new AsyncLocalStorage();
let instance;
export function setRuntime(runtime) { instance = runtime; }
export function runtime() { if (!instance) throw new Error('Standalone runtime is not initialized.'); return instance; }
export const secrets = { get: name => process.env[name] };
const pending = new Set();
export function waitUntil(value) {
  const promise = Promise.resolve(value); pending.add(promise);
  promise.catch(error => console.error('[background]', error.message)).finally(() => pending.delete(promise));
}
export const backgroundTasks = () => [...pending];

import { readFile, writeFile } from 'node:fs/promises';
const [action, filename] = process.argv.slice(2);
if (!['import','export'].includes(action) || !filename) {
  console.error('Usage: node --env-file-if-exists=.env standalone/server/data.mjs import|export records.json');
  process.exit(1);
}
const base = (process.env.PUBLIC_URL || 'http://localhost:3000').replace(/\/$/,'');
let token;
try {
  const response = await fetch(base+'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:process.env.MIGRATION_EMAIL||process.env.ADMIN_EMAIL,password:process.env.MIGRATION_PASSWORD||process.env.ADMIN_PASSWORD})});
  const login = await response.json();
  if (!response.ok) throw new Error(login.error || 'Administrator login failed.');
  token = login.token;
  const data = action === 'import' ? await readFile(filename,'utf8') : undefined;
  if (data && Buffer.byteLength(data)>29*1024*1024) throw new Error('Split imports larger than 29 MB into smaller entity batches.');
  const result = await fetch(base+'/api/admin/'+action,{method:action==='import'?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:data});
  const output = await result.json();
  if (!result.ok) throw new Error(output.error || 'Migration failed.');
  if(action==='export') {await writeFile(filename,JSON.stringify(output,null,2),{mode:0o600});console.log('Export saved to '+filename);}
  else console.log(JSON.stringify(output,null,2));
} catch(error) {console.error(error.message);process.exitCode=1;}
finally {if(token)await fetch(base+'/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+token}}).catch(()=>{});}

import { spawn } from 'node:child_process';
const backend = spawn(process.execPath, ['standalone/server/index.mjs'], { stdio: 'inherit', env: { ...process.env, NODE_ENV: 'development' } });
const frontend = spawn(process.execPath, ['node_modules/vite/bin/vite.js', '--host', '127.0.0.1'], { stdio: 'inherit', env: process.env });
let closing = false;
const close = () => { if (closing) return; closing = true; backend.kill('SIGTERM'); frontend.kill('SIGTERM'); };
for (const signal of ['SIGINT','SIGTERM']) process.on(signal, close);
for (const child of [backend,frontend]) child.on('exit', code => { close(); if (code) process.exitCode = code; });

import { mkdir, writeFile, readFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { randomUUID, createHmac, timingSafeEqual } from 'node:crypto';
import { HttpError } from './query.mjs';

export class Files {
  constructor(store, directory, publicUrl) { this.store = store; this.directory = resolve(directory); this.publicUrl = publicUrl.replace(/\/$/, ''); }
  async upload(file, privateFile, context) {
    if (!context.user && !context.service) throw new HttpError(401, 'Sign in required.');
    if (!file || typeof file.arrayBuffer !== 'function') throw new HttpError(400, 'A file is required.');
    if (file.size > 25 * 1024 * 1024) throw new HttpError(413, 'File exceeds 25 MB.');
    const id = randomUUID(), name = String(file.name || 'file').replace(/[\r\n\0/\\]/g, '_').slice(0, 200);
    const bytes = Buffer.from(await file.arrayBuffer());
    await mkdir(this.directory, { recursive: true }); await writeFile(resolve(this.directory, id), bytes, { mode: 0o600 });
    this.store.db.prepare('INSERT INTO files(id,owner_id,private,name,type,size) VALUES (?,?,?,?,?,?)').run(id, context.user?.id || 'system', Number(privateFile), name, String(file.type || 'application/octet-stream'), bytes.length);
    const uri = (privateFile ? 'private://' : 'public://') + id;
    return { file_url: privateFile ? undefined : this.publicUrl + '/api/files/' + id, file_uri: uri, id, file_name: name };
  }
  metadata(uri) {
    let id = String(uri || '').replace(/^(private|public):\/\//, '');
    if (/^https?:/.test(id)) { const url = new URL(id); if (url.origin !== new URL(this.publicUrl).origin) return null; id = url.pathname.split('/').at(-1); }
    if (!/^[a-zA-Z0-9-]+$/.test(id)) return null;
    return this.store.db.prepare('SELECT * FROM files WHERE id=?').get(id) || null;
  }
