    for (const key of SYSTEM) delete data[key];
    const record = { ...previous, ...data, updated_date: new Date().toISOString() };
    if (!this.allowed(name, 'update', record, context)) throw new HttpError(403, 'This change would violate record access rules.');
    this.validate(name, record);
    this.db.prepare('UPDATE records SET data=? WHERE entity=? AND id=?').run(JSON.stringify(record), name, String(id));
    this.emit(name, { type: 'update', data: record, id: record.id });
    return this.visible(name, record, context);
  }
  delete(name, id, context = {}) {
    const record = this.raw(name, id);
    if (!record || !this.allowed(name, 'delete', record, context)) throw new HttpError(404, 'Record not found or cannot be deleted.');
    this.db.prepare('DELETE FROM records WHERE entity=? AND id=?').run(name, String(id));
    this.emit(name, { type: 'delete', data: record, id: record.id }); return { success: true, id };
  }
  emit(name, event) { if (this.pendingEvents) this.pendingEvents.push([name,event]); else { try { this.events.emit(name,event); } catch {} } }
  atomic(operation) {
    const nested = this.db.isTransaction;
    if (nested) return operation();
    this.db.exec('BEGIN IMMEDIATE'); this.pendingEvents = [];
    try { const result = operation(); this.db.exec('COMMIT'); const pending = this.pendingEvents; this.pendingEvents = null; pending.forEach(([name,event]) => this.emit(name,event)); return result; }
    catch (error) { this.db.exec('ROLLBACK'); this.pendingEvents = null; throw error; }
  }
  close() { this.db.close(); }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, writeFile, rm, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve, join } from 'node:path';
import { Store } from '../server/store.mjs';
import { Auth } from '../server/auth.mjs';
import { matches, permits } from '../server/query.mjs';
