test('query operators and mixed row-level rules preserve access restrictions', () => {
  assert.equal(matches({ amount: 7, tags: ['a','b'] }, { amount: { $gte: 5, $lt: 9 }, tags: { $in: ['b'] } }), true);
  assert.equal(permits({ $or: [{ user_condition: { role: 'admin' } }, { 'data.owner': '{{user.id}}' }], 'data.active': true }, { owner: 'u1', active: false }, { id: 'u1', role: 'user' }), false);
  assert.equal(permits({ 'data.tenant': '{{user.data.tenant}}' }, {}, { id: 'u1' }), false);
});
test('record and field rules stop cross-user reads, ownership changes and blind secret filtering', async () => {
  const temp = await mkdtemp(join(tmpdir(), 'runtime-rls-'));
  try {
    const schemas = join(temp,'schemas'); await mkdir(schemas);
    const owner = { 'data.owner_id': '{{user.id}}' };
    await writeFile(join(schemas,'Task.json'),JSON.stringify({ name:'Task',properties:{ owner_id:{type:'string'},title:{type:'string'},secret:{type:'string',rls:{read:false,write:false}} },required:['owner_id','title'],rls:{create:owner,read:owner,update:owner,delete:owner} }));
    const store = new Store({path:':memory:',schemaDir:schemas}), alice={user:{id:'alice',role:'user'}}, bob={user:{id:'bob',role:'user'}};
    const record = store.create('Task',{owner_id:'alice',title:'Private',secret:'hidden-value'},{service:true});
    assert.equal(store.get('Task',record.id,alice).secret,undefined);
    assert.equal(store.query('Task',{secret:{$regex:'hidden'}},undefined,100,0,alice).length,0);
    assert.equal(store.count('Task',{secret:'hidden-value'},alice),0);
    assert.throws(()=>store.get('Task',record.id,bob),/not found/);
    assert.throws(()=>store.update('Task',record.id,{owner_id:'bob'},alice),/access rules/);
    assert.throws(()=>store.update('Task',record.id,{secret:'changed'},alice),/cannot change/);
    let events=0; store.events.on('Task',()=>events++);
    assert.throws(()=>store.atomic(()=>{store.create('Task',{owner_id:'alice',title:'Temporary'},alice);store.create('Task',{owner_id:'alice'},alice);}),/required/);
    assert.equal(store.count('Task',{},alice),1); assert.equal(events,0); store.close();
  } finally { await rm(temp,{recursive:true,force:true}); }
});
test('password hashing, session expiry and logout work without hosted authentication', async () => {
  const store = new Store({path:':memory:',schemaDir:null}), auth = new Auth(store);
  const user=await auth.create({email:'test@example.com',password:'temporary-test-password',role:'user'});
  await assert.rejects(()=>auth.login('test@example.com','incorrect'),/incorrect/);
  const session=await auth.login('test@example.com','temporary-test-password');
  const request=new Request('http://localhost/api/auth/me',{headers:{Authorization:'Bearer '+session.token}});
  assert.equal(auth.user(request).id,user.id);
  assert.equal(store.raw('User',user.id).password,undefined);
  assert.throws(()=>store.update('User',user.id,{role:'admin'},{user}),/administrator/);
  auth.logout(request);assert.equal(auth.user(request),null);store.close();
});
test('data migration preserves imported user ownership and links existing local accounts', async () => {
  const store=new Store({path:':memory:',schemaDir:null}),auth=new Auth(store);
  try {
    const admin=await auth.create({email:'admin@example.com',password:'temporary-admin-password',role:'admin'});
    importRecords(store,{entities:{User:[{id:'hosted-admin',email:admin.email,role:'user'},{id:'hosted-member',email:'member@example.com',full_name:'Member',role:'user',password_hash:'discard'}],RuntimeEvent:[]}},admin);
    assert.fail('Reserved models must be rejected');
  } catch(error) {assert.match(error.message,/Invalid entity/);assert.equal(store.count('User',{}, {service:true}),1);}
  const admin=store.query('User',{},undefined,1,0,{service:true})[0];
  const result=importRecords(store,{entities:{User:[{id:'hosted-admin',email:admin.email,role:'user'},{id:'hosted-member',email:'member@example.com',role:'user',password_hash:'discard'}]}},admin);
  assert.equal(result.remapped_user_ids['hosted-admin'],admin.id);assert.equal(store.raw('User',admin.id).role,'admin');
  const member=await auth.create({email:'member@example.com',password:'temporary-member-password',role:'user'});
  assert.equal(member.id,'hosted-member');assert.equal(store.raw('User',member.id).password_hash,undefined);store.close();
});
test('converted S4 functions, authentication, files, entity APIs and collaboration run on the independent server', {skip:!existsSync('base44/functions/attendance/entry.ts') || !existsSync('base44/actors/S4SheetRoom/entry.ts')}, async () => {
  const temp=await mkdtemp(join(tmpdir(),'s4-runtime-'));
  let instance;
  try {
    instance=await startServer({port:0,root:process.cwd(),db:join(temp,'app.sqlite'),uploadDir:join(temp,'uploads')});
    const {app}=instance, base='http://127.0.0.1:'+instance.port;
    const admin=await app.auth.create({email:'admin-test@example.com',password:'temporary-admin-test-password',role:'admin'});
    const member=await app.auth.create({email:'member-test@example.com',password:'temporary-member-test-password',role:'user'});
    const login=await fetch(base+'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:admin.email,password:'temporary-admin-test-password'})});
    assert.equal(login.status,200);const session=await login.json(),cookie=login.headers.get('set-cookie').split(';')[0];
    const headers={Authorization:'Bearer '+session.token,'Content-Type':'application/json'};
    const post=(path,data,authHeaders=headers)=>fetch(base+path,{method:'POST',headers:authHeaders,body:JSON.stringify(data)});
    assert.equal((await fetch(base+'/api/auth/me')).status,401);
    assert.equal((await post('/api/functions/attendance',{employee_id:'test'} ,{'Content-Type':'application/json'})).status,401);
    assert.equal((await post('/api/entities/RuntimeInvitation/create',{args:[{role:'admin',token:'bad',user_id:member.id}]})).status,403);
    const functions=(await readdir('base44/functions',{withFileTypes:true})).filter(entry=>entry.isDirectory());
    for(const entry of functions) await app.loadFunction(entry.name);
    assert.equal(functions.length>=62,true);
    const employee=app.store.create('PMEmployee',{employee_id:'TEST001',full_name:'Test Employee',email:'test-employee@example.com'},{service:true});
    const attendance=await post('/api/functions/attendance',{employee_id:'TEST001',auth_datetime:'2026-10-25T08:00:00Z',device_id:'TEST'});
    assert.equal(attendance.status,200,await attendance.clone().text());assert.equal((await attendance.json()).action,'clock_in');
    const later=await post('/api/functions/attendance',{employee_id:'TEST001',auth_datetime:'2026-10-25T17:00:00Z',device_id:'TEST'});
    assert.equal((await later.json()).action,'clock_out');
    assert.equal(app.store.query('Attendance',{},undefined,10,0,{service:true}).length,1);
    const form=new FormData();form.append('file',new File(['private test data'],'test.txt',{type:'text/plain'}));
    const upload=await fetch(base+'/api/integrations/UploadPrivateFile',{method:'POST',headers:{Authorization:'Bearer '+session.token},body:form});
    assert.equal(upload.status,200);const file=await upload.json();
    assert.equal((await fetch(base+'/api/files/'+file.id)).status,403);
    const signed=await post('/api/integrations/CreateFileSignedUrl',{file_uri:file.file_uri,expires_in:60});
    const signedUrl=new URL((await signed.json()).signed_url);signedUrl.host=new URL(base).host;
    assert.equal(await (await fetch(signedUrl)).text(),'private test data');
    const sheet=app.store.create('Spreadsheet',{name:'Test workbook',owner_id:admin.id,room_id:'test-room',member_ids:[]},{service:true});
    app.store.create('Worksheet',{spreadsheet_id:sheet.id,name:'Sheet1',owner_id:admin.id,position:0},{service:true});
    const socket=new WebSocket(base.replace('http:','ws:')+'/api/actors/S4SheetRoom/test-room',{headers:{Cookie:cookie}});
    const initial=await new Promise((resolve,reject)=>{
      const timer=setTimeout(()=>reject(new Error('Collaboration room did not return initial state')),10000);
      socket.on('error',reject);socket.on('message',bytes=>{const message=JSON.parse(bytes);if(message.type==='connected')socket.send(JSON.stringify({type:'join',spreadsheetId:sheet.id,name:'Admin'}));if(message.type==='initial'){clearTimeout(timer);resolve(message);}});
    });
    assert.equal(initial.sheet.id,sheet.id);socket.close();
    const me=await fetch(base+'/api/auth/me',{headers});const profile=await me.json();assert.equal(profile.id,admin.id);assert.equal(profile.hash,undefined);
    console.log('Verified '+functions.length+' imported function modules, local attendance workflow and spreadsheet room.');
  } finally {if(instance)await instance.close();await rm(temp,{recursive:true,force:true});}
});
